require_once __DIR__.'/../config/database.php';if(empty($_SESSION['user'])||($_SESSION['user']['role']??'')!=='admin'){http_response_code(403);exit('Akses ditolak');}$users=$conn->query("SELECT id,nama_lengkap,username,email,role,created_at FROM users ORDER BY id DESC")->fetch_all(MYSQLI_ASSOC);?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><title>Data User</title></head><body><main class="container py-4"><h2>Pengguna Terdaftar</h2><a class="btn btn-secondary mb-3" href="index.php">Dashboard</a><div class="table-responsive"><table class="table table-bordered"><tr><th>#</th><th>Nama</th><th>Username</th><th>Email</th><th>Role</th><th>Terdaftar</th></tr><?php foreach($users as $u):?><tr><td><?=$u['id']?></td><td><?=htmlspecialchars($u['nama_lengkap'])?></td><td><?=htmlspecialchars($u['username'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><?=$u['role']?></td><td><?=htmlspecialchars($u['created_at']??'-')?></td></tr><?php endforeach;?></table></div></main></body></html>